(function(){
  const colors = PALETTE;
  const cw = ()=>W(), ch=()=>H();
  let t = 0;
  const clouds = [];
  for(let i=0;i<4;i++){
    clouds.push({
      x: Math.random()*cw(),
      y: Math.random()*ch()*0.4,
      rx: 150+Math.random()*120,
      ry: 60+Math.random()*40,
      speed: (Math.random()*0.15+0.05)*(Math.random()<0.5?1:-1),
      alpha: 0.05+Math.random()*0.05
    });
  }
  const fruit = {x: cw()*0.82, y: ch()*0.18, r: Math.min(cw(),ch())*0.085};
  let slices = [];
  let spawnTimer = 0;
  const sparks = [];
  const NS = 90;
  for(let i=0;i<NS;i++){
    sparks.push({
      x: Math.random()*cw(),
      y: Math.random()*ch(),
      r: Math.random()*1.6+0.5,
      vy: -(Math.random()*0.12+0.03),
      vx: (Math.random()-0.5)*0.04,
      alpha: Math.random()*0.4+0.15,
      phase: Math.random()*Math.PI*2
    });
  }
  function drawBranch(x0,y0,dir){
    ctx.save();
    ctx.strokeStyle = colors[1];
    ctx.globalAlpha = 0.35;
    ctx.lineWidth = 2;
    ctx.beginPath();
    ctx.moveTo(x0,y0);
    const cx1 = x0+dir*60, cy1=y0-40;
    const cx2 = x0+dir*120, cy2=y0-20;
    const ex = x0+dir*170, ey=y0-70;
    ctx.bezierCurveTo(cx1,cy1,cx2,cy2,ex,ey);
    ctx.stroke();
    ctx.restore();
    for(let i=0;i<2;i++){
      const p = 0.4+i*0.3;
      const bx = x0+dir*170*p;
      const by = y0-70*p - 10;
      ctx.save();
      ctx.beginPath();
      ctx.fillStyle = colors[0];
      ctx.globalAlpha = 0.5;
      ctx.arc(bx,by, 8+i*2, 0, Math.PI*2);
      ctx.fill();
      ctx.restore();
    }
  }
  function frame(){
    const w = cw(), h = ch();
    ctx.clearRect(0,0,w,h);
    t += 1;
    clouds.forEach(c=>{
      c.x += c.speed;
      if(c.x < -c.rx) c.x = w+c.rx;
      if(c.x > w+c.rx) c.x = -c.rx;
      const g = ctx.createRadialGradient(c.x,c.y,0,c.x,c.y,c.rx);
      g.addColorStop(0, colors[1]+'22');
      g.addColorStop(1, colors[1]+'00');
      ctx.save();
      ctx.filter = 'blur(2px)';
      ctx.fillStyle = g;
      ctx.beginPath();
      ctx.ellipse(c.x,c.y,c.rx,c.ry,0,0,Math.PI*2);
      ctx.fill();
      ctx.restore();
    });
    drawBranch(w*0.06, h*0.98, 1);
    drawBranch(w*0.94, h*0.98, -1);
    const pulse = 1 + Math.sin(t*0.02)*0.06;
    ctx.save();
    ctx.shadowColor = colors[0];
    ctx.shadowBlur = 40*pulse;
    const grad = ctx.createRadialGradient(fruit.x,fruit.y,0,fruit.x,fruit.y,fruit.r*pulse);
    grad.addColorStop(0, colors[2]);
    grad.addColorStop(0.5, colors[0]);
    grad.addColorStop(1, colors[0]+'00');
    ctx.fillStyle = grad;
    ctx.beginPath();
    ctx.arc(fruit.x, fruit.y, fruit.r*pulse, 0, Math.PI*2);
    ctx.fill();
    ctx.restore();
    ctx.save();
    ctx.translate(fruit.x, fruit.y - fruit.r*0.7);
    ctx.rotate(Math.sin(t*0.01)*0.05);
    ctx.fillStyle = colors[1];
    ctx.globalAlpha = 0.6;
    for(let i=0;i<4;i++){
      ctx.save();
      ctx.rotate(i*Math.PI/2);
      ctx.beginPath();
      ctx.moveTo(0,0);
      ctx.lineTo(fruit.r*0.35, fruit.r*0.25);
      ctx.lineTo(0, fruit.r*0.5);
      ctx.lineTo(-fruit.r*0.35, fruit.r*0.25);
      ctx.closePath();
      ctx.fill();
      ctx.restore();
    }
    ctx.restore();
    spawnTimer++;
    if(spawnTimer > 55 && slices.length < 14){
      spawnTimer = 0;
      slices.push({
        x: fruit.x + (Math.random()-0.5)*fruit.r*0.6,
        y: fruit.y + (Math.random()-0.5)*fruit.r*0.4,
        rx: fruit.r*(0.5+Math.random()*0.3),
        ry: fruit.r*(0.2+Math.random()*0.15),
        rot: Math.random()*Math.PI,
        vy: 0.25+Math.random()*0.2,
        vx: (Math.random()-0.5)*0.15,
        vr: (Math.random()-0.5)*0.01,
        life: 0,
        maxLife: 500+Math.random()*200
      });
    }
    slices.forEach(s=>{
      s.x += s.vx;
      s.y += s.vy;
      s.rot += s.vr;
      s.life++;
    });
    slices = slices.filter(s=>s.life < s.maxLife && s.y < h+100);
    slices.forEach(s=>{
      const lifeRatio = s.life/s.maxLife;
      const alpha = Math.sin(Math.min(lifeRatio*Math.PI, Math.PI)) * 0.35;
      const dx = s.x - w*0.5, dy = s.y - h*0.5;
      const distCenter = Math.sqrt(dx*dx+dy*dy);
      const centerFade = distCenter < Math.min(w,h)*0.22 ? 0.3 : 1;
      ctx.save();
      ctx.translate(s.x, s.y);
      ctx.rotate(s.rot);
      ctx.globalAlpha = alpha*centerFade;
      const g2 = ctx.createLinearGradient(-s.rx,0,s.rx,0);
      g2.addColorStop(0, colors[2]+'00');
      g2.addColorStop(0.5, colors[0]);
      g2.addColorStop(1, colors[2]+'00');
      ctx.fillStyle = g2;
      ctx.beginPath();
      ctx.ellipse(0,0,s.rx,s.ry,0,0,Math.PI*2);
      ctx.fill();
      ctx.restore();
    });
    sparks.forEach(sp=>{
      sp.x += sp.vx + Math.sin(t*0.01+sp.phase)*0.05;
      sp.y += sp.vy;
      if(sp.y < -10){ sp.y = h+10; sp.x = Math.random()*w; }
      if(sp.x < -10) sp.x = w+10;
      if(sp.x > w+10) sp.x = -10;
      const dx = sp.x - w*0.5, dy = sp.y - h*0.5;
      const distCenter = Math.sqrt(dx*dx+dy*dy);
      const centerFade = distCenter < Math.min(w,h)*0.24 ? 0.15 : 1;
      const flicker = 0.6+0.4*Math.sin(t*0.05+sp.phase);
      ctx.save();
      ctx.globalAlpha = sp.alpha*flicker*centerFade;
      ctx.fillStyle = colors[2];
      ctx.shadowColor = colors[0];
      ctx.shadowBlur = 6;
      ctx.beginPath();
      ctx.arc(sp.x, sp.y, sp.r, 0, Math.PI*2);
      ctx.fill();
      ctx.restore();
    });
    requestAnimationFrame(frame);
  }
  frame();
})();
